import json
import re
import html
from html.parser import HTMLParser

sources = json.load(open('source.json'))
refs = json.load(open('reference-targets.json'))

def paragraphs(*items):
    return '\n'.join('<p>' + html.escape(item, quote=False) + '</p>' for item in items)

def plain(value):
    return html.unescape(re.sub(r'<[^>]+>', '', value or ''))

answers = []
for src in sources:
    answers.append({key: src[key] for key in ('code_id', 'source_id', 'source_sha256', 'number')})
    answers[-1]['status'] = 'rewrite_draft'

def impact(i, classification, assessment, limitations, burdens, effects):
    answers[i]['substantive_impact'] = dict(version=1, classification=classification,
        assessment=assessment, scope_limitations=limitations,
        new_burdens_review=burdens, effects=effects)

def effect(kind, measure_id, description, before, after, unit, population, transition, replacement, source_quote, proposed_quote):
    return dict(kind=kind, measure_id=measure_id, description=description,
        before=before, after=after, unit=unit, affected_population=population,
        conditions_and_transition=transition, replacement_or_new_burdens=replacement,
        source_quote=source_quote, proposed_quote=proposed_quote)

def reduction(i, *removed):
    answers[i].update(change_type='normative_reduction', reform_policy_id='editorial_direction_2026_10_19', removed_provisions=list(removed))

def repeal(i, scope):
    answers[i].update(change_type='full_repeal', repeal_policy_id='editorial_direction_2026_10_19', repeal_scope=scope)

