for i, a in enumerate(answers):
    source_key = a['code_id'] + '|' + a['source_id']
    a['reference_checks'] = []
    for key in refs['requirements'][source_key]:
        target = refs['targets'][key]
        a['reference_checks'].append(dict(target_key=key,
            view_sha256=target['view_sha256'], assessment=checks[i][target['number']]))

# Le plafond VRP est déjà de trois mois : son absorption est une coordination,
# pas une réduction supplémentaire de durée ou une économie de conformité.
a = answers[3]
a['reason'] = "Coordination du contrat unique, avec abrogation prospective du fondement spécial d'essai VRP devenu doublon du maximum commun de trois mois. Ce rattachement ne réduit ni le maximum d'essai, déjà de trois mois, ni une formalité autonome démontrée ; aucune économie indépendante n'est revendiquée. Le caractère facultatif, les durées plus courtes et les anciens essais sont protégés. L'interdiction de renouvellement et le préavis de quinze jours relèvent des mesures générales coordonnées. Ce dernier peut augmenter la prévenance du salarié ; sa charge est décrite sans être recomptée comme une nouvelle réforme propre aux VRP. Supprimer aussi la garantie de durée, les droits antérieurs ou le reliquat payé retirerait des protections favorables sans justification essentielle."
imp = a['substantive_impact']
imp['classification'] = 'coordination_only'
imp['assessment'] = "Le fondement spécial est absorbé par le régime commun proposé, mais le maximum VRP reste trois mois : aucune réduction indépendante de durée, de montant ou de formalité n'est démontrée. Le préavis salarié passe à quinze jours par coordination de la mesure générale ; cet alourdissement est décrit dans les effets et le contrôle des charges, sans compter une seconde mesure. Le coût et la complexité nets ne sont pas établis."
for e in imp['effects']:
    e['kind'] = 'coordination'
imp['effects'][0]['description'] = "Rattachement au régime commun proposé d'essai, sans réduction du maximum spécial déjà fixé à trois mois ni suppression autonome de formalité démontrée."
imp['effects'][1]['description'] = "Coordination du préavis général de quinze jours, qui alourdit concrètement la prévenance du salarié en essai ; aucun gain propre à cet article n'est revendiqué."

with open('answer.json', 'w') as f:
    json.dump(answers, f, ensure_ascii=False, indent=2)
    f.write('\n')

# Contrôle de structure et de traçabilité seulement, pas validation du droit.
class XmlSubset(HTMLParser):
    allowed = set('p br table thead tbody tfoot tr th td b strong i em u sup sub ul ol li div span blockquote'.split())
    def handle_starttag(self, tag, attrs):
        assert tag in self.allowed, tag
        for name, value in attrs:
            assert name in ('rowspan', 'colspan') and value.isdigit(), (name, value)

positive = {'tax_removed', 'tax_reduced', 'obligation_removed', 'obligation_merged', 'authorization_removed', 'regime_merged', 'deadline_reduced', 'compliance_cost_reduced', 'relief_extended'}
negative = {'tax_increased', 'obligation_added', 'deadline_increased', 'complexity_added'}
for src, a in zip(sources, answers):
    for key in ('code_id', 'source_id', 'source_sha256', 'number'):
        assert a[key] == src[key]
    assert a['status'] in ('rewrite_draft', 'retained_unchanged')
    if a['status'] == 'retained_unchanged':
        assert a['proposed_xml'] is None
        assert a['substantive_impact']['classification'] == 'retained_necessary'
        assert not a['substantive_impact']['effects']
    else:
        assert a['proposed_xml']
        XmlSubset().feed(a['proposed_xml'])
    if src.get('benefit_check_required'):
        assert len(a['benefit_review']) >= 100
    imp = a['substantive_impact']
    assert imp['version'] == 1
    for key in ('assessment', 'scope_limitations', 'new_burdens_review'):
        assert len(imp[key]) >= 40
    kinds = set()
    for e in imp['effects']:
        assert len(e['source_quote']) >= 12
        assert len(e['proposed_quote']) >= 12
        assert e['source_quote'] in plain(src['source_xml']), (a['number'], 'source', e['source_quote'])
        assert e['proposed_quote'] in plain(a['proposed_xml']), (a['number'], 'proposed', e['proposed_quote'])
        assert re.fullmatch(r'[a-z0-9]+(?:-[a-z0-9]+)+', e['measure_id'])
        assert 6 <= len(e['measure_id']) <= 96
        kinds.add(e['kind'])
    if imp['classification'] == 'mixed':
        assert kinds & positive and kinds & negative, (a['number'], kinds)
    if a.get('change_type') == 'full_repeal':
        assert plain(a['proposed_xml']).startswith(('Le présent article est abrogé', 'Abrogé'))
        assert len(a['repeal_scope']) >= 30
    if a.get('change_type') == 'normative_reduction':
        assert a['removed_provisions'] and all(len(x) >= 30 for x in a['removed_provisions'])
    required = refs['requirements'][a['code_id'] + '|' + a['source_id']]
    assert [x['target_key'] for x in a['reference_checks']] == required
    for x in a['reference_checks']:
        assert x['view_sha256'] == refs['targets'][x['target_key']]['view_sha256']
        assert len(x['assessment']) >= 80

print(json.dumps({'file': 'answer.json', 'articles': len(answers), 'reference_checks': sum(len(a['reference_checks']) for a in answers), 'classifications': {a['number']: a['substantive_impact']['classification'] for a in answers}}, ensure_ascii=False, indent=2))
